 1	// Storage layer. Everything lives in this browser's localStorage: no server, no account, no sync.
 2	// Clearing site data, switching browser or switching device means starting from an empty list.
 3	const STORE_KEY = 'todo.v1';
 4	
 5	const store = {
 6	  load() {
 7	    try {
 8	      return JSON.parse(localStorage.getItem(STORE_KEY)) || [];
 9	    } catch {
10	      return [];
11	    }
12	  },
13	  save(todos) {
14	    // localStorage is capped per origin (about 5 MB in most browsers). A failed write is only logged.
15	    try {
16	      localStorage.setItem(STORE_KEY, JSON.stringify(todos));
17	    } catch (err) {
18	      console.error('save failed', err);
19	    }
20	  },
21	};
 1	// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
 2	let todos = store.load();
 3	let filter = 'all';
 4	
 5	const $ = (sel) => document.querySelector(sel);
 6	
 7	function add(title) {
 8	  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
 9	  commit();
10	}
11	
12	function toggle(id) {
13	  const t = todos.find((x) => x.id === id);
14	  if (t) t.done = !t.done;
15	  commit();
16	}
17	
18	function remove(id) {
19	  todos = todos.filter((x) => x.id !== id);
20	  commit();
21	}
22	
23	function commit() {
24	  store.save(todos);
25	  render();
26	}
27	
28	function visible() {
29	  if (filter === 'open') return todos.filter((t) => !t.done);
30	  if (filter === 'done') return todos.filter((t) => t.done);
31	  return todos;
32	}
33	
34	function render() {
35	  const list = $('#list');
36	  list.innerHTML = '';
37	  for (const t of visible()) {
38	    const li = document.createElement('li');
39	    li.className = t.done ? 'done' : '';
40	    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
41	    li.querySelector('span').textContent = t.title;
42	    li.querySelector('input').onchange = () => toggle(t.id);
43	    li.querySelector('button').onclick = () => remove(t.id);
44	    list.append(li);
45	  }
46	  const open = todos.filter((t) => !t.done).length;
47	  $('#count').textContent = `${open} việc chưa xong`;
48	}
49	
50	$('#add').onsubmit = (e) => {
51	  e.preventDefault();
52	  const input = $('#title');
53	  if (input.value.trim()) add(input.value);
54	  input.value = '';
55	};
56	
57	$('#filters').onclick = (e) => {
58	  const f = e.target.dataset.filter;
59	  if (!f) return;
60	  filter = f;
61	  document.querySelectorAll('#filters button').forEach((b) => b.classList.toggle('on', b.dataset.filter === f));
62	  render();
63	};
64	
65	render();
