 2	<html lang="vi">
 3	<head>
 4	  <meta charset="utf-8">
 5	  <meta name="viewport" content="width=device-width, initial-scale=1">
 6	  <title>Todo</title>
 7	  <link rel="stylesheet" href="style.css">
 8	</head>
 9	<body>
10	  <main>
11	    <h1>Todo</h1>
12	    <form id="add">
13	      <input id="title" placeholder="Việc cần làm…" autocomplete="off" required>
14	      <button>Thêm</button>
15	    </form>
16	    <nav id="filters">
17	      <button data-filter="all" class="on">Tất cả</button>
18	      <button data-filter="open">Chưa xong</button>
19	      <button data-filter="done">Đã xong</button>
20	    </nav>
21	    <ul id="list"></ul>
22	    <p id="count"></p>
23	  </main>
24	  <script src="store.js"></script>
25	  <script src="app.js"></script>
26	</body>
27	</html>
 1	body { font: 16px/1.5 system-ui, sans-serif; background: #f6f6f4; color: #222; margin: 0; }
 2	main { max-width: 32rem; margin: 3rem auto; padding: 0 1rem; }
 3	form { display: flex; gap: .5rem; }
 4	input#title { flex: 1; padding: .5rem; }
 5	nav { margin: 1rem 0; display: flex; gap: .25rem; }
 6	nav button.on { font-weight: 700; }
 7	ul { list-style: none; padding: 0; }
 8	li { display: flex; justify-content: space-between; padding: .4rem 0; border-bottom: 1px solid #ddd; }
 9	li.done span { text-decoration: line-through; color: #888; }

